<?php
require __DIR__.'/includes/bootstrap.php';require_login();
$page_title='Мой кабинет';$u=current_user();
$s=$pdo->prepare('SELECT v.*,(SELECT COUNT(*) FROM fines f WHERE f.vehicle_id=v.id AND f.status="issued") AS open_fines FROM vehicles v WHERE v.owner_user_id=? OR LOWER(v.owner_email)=LOWER(?) ORDER BY v.created_at DESC');$s->execute([$u['id'],$u['email']]);$vehicles=$s->fetchAll();
$s=$pdo->prepare('SELECT f.*,v.plate,v.make,v.model FROM fines f JOIN vehicles v ON v.id=f.vehicle_id WHERE LOWER(v.owner_email)=LOWER(?) ORDER BY f.created_at DESC LIMIT 10');$s->execute([$u['email']]);$fines=$s->fetchAll();
include __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow">Личный кабинет</span><h1>Здравствуйте, <?= e($u['full_name']) ?></h1><p>Ваши транспортные средства, регистрационные сведения и начисления.</p></section>
<div class="stats-grid"><div class="stat-card"><div class="stat-icon">▣</div><div><strong><?= count($vehicles) ?></strong><span>Автомобилей привязано</span></div></div><div class="stat-card"><div class="stat-icon">₽</div><div><strong><?= count(array_filter($fines,fn($f)=>$f['status']==='issued')) ?></strong><span>Активных штрафов</span></div></div><div class="stat-card"><div class="stat-icon">◉</div><div><strong><?= e(role_label($u['role'])) ?></strong><span>Роль аккаунта</span></div></div></div>
<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Мои автомобили</h2><p>Транспорт, зарегистрированный на вашу почту</p></div><?php if($vehicles): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Госномер</th><th>Автомобиль</th><th>VIN</th><th>Штрафы</th><th></th></tr></thead><tbody><?php foreach($vehicles as $v): ?><tr><td><span class="license-plate plate-sm"><?= e($v['plate']) ?></span></td><td><strong><?= e($v['make'].' '.$v['model']) ?></strong><br><span class="muted tiny"><?= e($v['year']) ?> · <?= e($v['color']?:'цвет не указан') ?></span></td><td><?= e($v['vin']) ?></td><td><span class="badge <?= (int)$v['open_fines']?'badge-yellow':'badge-green' ?>"><?= (int)$v['open_fines'] ?></span></td><td><a class="btn btn-ghost btn-small" href="vehicle.php?id=<?= (int)$v['id'] ?>">Открыть →</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">▣</div><h2>Автомобили ещё не привязаны</h2><p>При регистрации транспортного средства сотрудник ГИБДД должен указать email, используемый в вашем аккаунте.</p></div><?php endif; ?></section>
<section class="panel"><div class="panel-header"><h2>Последние начисления</h2><p>Штрафы, оформленные на ваш адрес электронной почты</p></div><?php if($fines): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Постановление</th><th>Автомобиль</th><th>Сумма</th><th>Срок оплаты</th><th>Статус</th><th>Банк</th></tr></thead><tbody><?php foreach($fines as $f): ?><tr><td><strong><?= e($f['external_ref']) ?></strong><br><span class="muted tiny"><?= e($f['title']) ?></span></td><td><?= e($f['plate']) ?> · <?= e($f['make'].' '.$f['model']) ?></td><td><strong><?= money($f['amount']) ?></strong></td><td><?= e($f['due_date']) ?></td><td><span class="badge <?= $f['status']==='paid'?'badge-green':'badge-yellow' ?>"><?= e(status_label($f['status'])) ?></span></td><td><span class="badge <?= $f['bank_status']==='sent'?'badge-green':($f['bank_status']==='error'?'badge-red':'badge-yellow') ?>"><?= e(status_label($f['bank_status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">₽</div><h2>Начислений пока нет</h2><p>Если сотрудник ГИБДД оформит штраф на ваш автомобиль, он появится здесь.</p></div><?php endif; ?></section>
<?php include __DIR__.'/includes/footer.php'; ?>
